/* A quieter entry and a continuous workshop-to-independent-learning journey. */
(()=>{
 const C=window.REILearningPathCore;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const read=()=>window.REILearningStore.readPath();
 const link=(href,text,cls='path-link')=>`<a class="${cls}" href="${href}">${text}<span aria-hidden="true">↗</span></a>`;
 function tabs(current){return `<nav class="path-tabs" aria-label="Learning workspace">${[['#learn','Learning path','learn'],['#practice','Practice lab','practice'],['#workbook','My workbook','workbook']].map(([href,label,key])=>`<a href="${href}" ${key===current?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`}
 function shell(body,current='learn'){return `<div class="path-page" data-learning-surface>${tabs(current)}${body}<footer class="path-help"><p>Your workbook saves in this browser. No account or automatic sharing.</p><div>${link('#backup','Back up or restore')}${link('#learning-evidence','How the learning activities were designed')}${link('#explore','Explore REI’s optical story')}</div></footer></div>`}
 function landing(){const s=read(),has=Object.values(s.fields).some(x=>x.trim());return `<div class="path-page path-landing" data-learning-surface><section class="path-welcome"><div><h1>Learn to ask.<br>Build the <em>evidence.</em></h1><p class="path-intro">A place to turn curiosity into research you can explain. Continue after the writeshop, or begin independently.</p><p>Learn a little, try it on your own question, then return with a stronger draft.</p></div><div class="path-identity"><div class="sculpture" data-sculpture="38" aria-hidden="true"><img class="sculpture-fallback" src="particle-fallback.svg" alt=""><canvas></canvas></div><p>Question → sources → connections → research blueprint</p></div></section><section class="path-entry" aria-label="Choose where to start"><article><span class="path-entry-type">I want to develop my skills</span><h2>A clear path.<br>One useful step at a time.</h2><p>Revisit the workshop ideas through short explanations, a personal workbook and practice with feedback.</p>${link('#learn',has?'Continue my learning':'Start learning','path-button')}</article><article><span class="path-entry-type">I have a research project</span><h2>Your evidence.<br>A place to work with it.</h2><p>Open your projects, organize sources, capture evidence and develop your proposal. Return to learning whenever you need it.</p>${link('#research','Open research studio','path-button')}</article></section><section class="path-start-note"><h2>New to research?</h2><p>Choose <strong>Start learning</strong>. You only need an idea or an observation—not a finished topic. Already have notes from the seminar? Bring them into the workbook at the matching step.</p>${link('#practice','Try a short practice activity')}</section><footer class="path-help">${link('#learning-evidence','The research behind the learning design')}${link('#explore','Explore the original REI experience')}<p>Saved on this device. Keep a backup to move your work.</p></footer></div>`}
 function rows(s,current=-1){return `<ol class="path-outline">${C.steps.map((step,i)=>{const count=step.fields.filter(([k])=>s.fields[k]?.trim()).length;return `<li><a href="#learn/${i}" ${i===current?'aria-current="step"':''}><span class="path-number">${String(i+1).padStart(2,'0')}</span><span><strong>${step.short}</strong><small>${count?count+' of '+step.fields.length+' prompts have notes':'No notes yet'}</small></span><span aria-hidden="true">→</span></a></li>`}).join('')}</ol>`}
 function dashboard(){const s=read(),n=C.next(s),has=Object.values(s.fields).some(x=>x.trim()),index=has?s.last:(n<0?5:n);return shell(`<section class="path-heading"><h1>Your research<br>starts <em>here.</em></h1><p>Follow the writeshop’s sequence at your own pace. Each step adds a small piece to one research blueprint. You can revisit any step. Your short responses save in My workbook.</p>${link('#learn/'+index,has?'Continue my last step':'Begin step 1','path-button')}</section><div class="path-dashboard"><section><div class="path-section-title"><h2>Your learning path</h2><span>Six connected steps</span></div>${rows(s)}<p class="path-muted">Recorded notes show where you have worked. They are not a grade or a measure of research quality.</p></section><aside class="path-next"><h2>${has?'Pick up your thinking.':'Begin with one observation.'}</h2><p>${has?'Your last edited step: '+esc(C.steps[index].short)+'. Skip to another step if that better fits your work.':'Write down something you have noticed and question your first explanation. You can refine it as you learn.'}</p><details><summary>How to use this space</summary><ol><li>Read the short explanation.</li><li>Write about your own research idea.</li><li>Try a practice activity and compare your reasoning.</li><li>Review your workbook, seek feedback and return to revise.</li></ol><p>Seminar participant? The phase names help you reconnect with your notes. Independent learner? Start at step 1; no seminar attendance is required.</p></details>${link('#practice','Explore eight practice activities')}${link('#workbook','See everything you have written')}</aside></div><section class="path-more"><h2>Go deeper when you need to.</h2><p>The nine original lessons include examples, guided writing and knowledge checks. You do not need to open every research tool to start learning.</p><div>${link('#academy','Browse the full lessons')}${link('#seminars','More self-guided workshops')}${link('#toolkit','Find a research template')}</div></section>`)}
 function stepView(i){if(!Number.isInteger(i)||!C.steps[i])return dashboard();const step=C.steps[i],s=read();return shell(`<div class="path-step-layout"><aside class="path-rail"><a class="path-back" href="#learn">← Learning home</a>${rows(s,i)}</aside><article class="path-step"><nav class="path-breadcrumb" aria-label="You are here"><a href="#learn">Learning path</a><span>Step ${i+1} of 6</span></nav><p class="path-origin">${esc(step.seminar)}</p><h1>${esc(step.title)}</h1><p class="path-intro">${esc(step.intro)}</p><div class="path-memory"><strong>Keep this in mind</strong><p>${esc(step.remember)}</p></div><ul class="path-concepts">${step.concepts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><details class="path-example"><summary>See a worked example</summary><p>${esc(step.example)}</p><p>Illustration only. Check evidence and requirements for your own discipline.</p></details><section class="path-writing"><h2>Make it yours</h2><p>Use your own idea or your seminar notes. You can leave a prompt and return to it later.</p><form data-path-form="${i}">${step.fields.map(([k,label,hint])=>`<label for="path-${k}">${esc(label)}<small id="help-${k}">${esc(hint)}</small><textarea id="path-${k}" name="${k}" rows="4" maxlength="3000" aria-label="${esc(label)}" aria-describedby="help-${k}">${esc(s.fields[k]||'')}</textarea></label>`).join('')}<p class="path-save" role="status" data-path-status>Notes save as you write on this device.</p><button type="submit" class="path-button">Save these notes</button></form></section><section class="path-extension"><h2>Try the reasoning somewhere new.</h2>${link('#practice/'+step.practice,C.activities.find(a=>a.id===step.practice).title,'path-button')}<details><summary>More help and research tools</summary>${step.links.map(([lesson,title])=>link('#lesson/'+lesson,esc(title))).join('')}${link(step.tool[0],step.tool[1])}<p>Project tools keep separate records. Nothing from this workbook is inserted into a proposal automatically.</p></details></section><nav class="path-step-actions" aria-label="Continue learning">${i?link('#learn/'+(i-1),'← Previous step'):link('#learn','Learning home')}${link(i===5?'#workbook':'#learn/'+(i+1),i===5?'Review my workbook':'Next: '+esc(C.steps[i+1].short),'path-button')}</nav></article></div>`)}
 function practiceHome(){const s=read();return shell(`<section class="path-heading"><h1>Practice the<br><em>research thinking.</em></h1><p>Try an unfamiliar situation, explain your choice, compare it with guidance and revise. These are fictional exercises, not automatic assessments of your study.</p></section><div class="path-section-title"><h2>Choose a skill to work on</h2><span>Return whenever you need practice</span></div><ol class="path-activity-list">${C.activities.map((a,i)=>{const r=s.practice[a.id];return `<li><span class="path-number">${String(i+1).padStart(2,'0')}</span><div><small>${esc(a.kind)}</small><h2>${link('#practice/'+a.id,esc(a.title))}</h2><p>${r?.revision?.trim()?'You have a revision to revisit.':r?.attempt?.trim()?'Your first attempt is saved.':'Start with a short written explanation.'}</p></div><a class="path-open" href="#practice/${a.id}" aria-label="Open ${esc(a.title)}">Open ↗</a></li>`}).join('')}</ol><section class="path-more"><h2>A small routine you can repeat.</h2><p>Recall without looking → compare with guidance → explain a correction → try a new example later. There is no daily streak or mastery score.</p>${link('#academy','Find the full lesson examples and scenarios')}${link('#learning-evidence','Read the evidence and its limits')}</section>`,'practice')}
 function comparison(a,r){return `${a.options?`<p class="path-feedback">${esc(a.feedback[r.choice]||'Compare each option against the evidence.')}</p>`:''}<h2>A comparison answer</h2><p>${esc(a.model)}</p><h3>Transfer it to your research</h3><p>${esc(a.transfer)}</p><label for="practice-revision">Your revision and why it is stronger<textarea id="practice-revision" name="revision" rows="6" maxlength="3000">${esc(r.revision||'')}</textarea></label><button class="path-button" type="button" data-path-reviewed="${a.id}">Save revision and record this visit</button><p class="path-muted">${r.reviewed?'Last review recorded '+esc(new Date(r.reviewed).toLocaleDateString())+'. ':''}A recorded visit is not evidence of mastery.</p>`}
 function activityView(id){const a=C.activities.find(x=>x.id===id);if(!a)return practiceHome();const r=read().practice[id]||{};return shell(`<article class="path-activity"><a class="path-back" href="#practice">← Practice lab</a><p class="path-origin">${esc(a.kind)}</p><h1>${esc(a.title)}</h1><p class="path-intro">${esc(a.prompt)}</p><form data-practice-form="${a.id}">${a.options?`<fieldset><legend>Choose a starting interpretation</legend>${a.options.map((x,i)=>`<label class="path-option"><input type="radio" name="choice" value="${i}" ${r.choice===i?'checked':''}>${esc(x)}</label>`).join('')}</fieldset>`:''}<label for="practice-attempt">Your first explanation<textarea id="practice-attempt" name="attempt" rows="6" maxlength="3000" placeholder="Try your reasoning before opening the comparison answer.">${esc(r.attempt||'')}</textarea></label><p role="status" class="path-save" data-path-status>Notes save as you write on this device.</p><button type="submit" class="path-button">${r.revealed?'Compare my reasoning again':'Compare my reasoning'}</button><section id="path-comparison" class="path-comparison" ${r.revealed?'':'hidden'}>${r.revealed?comparison(a,r):''}</section></form><details class="path-evidence-note"><summary>Why this kind of practice?</summary><p>This is REI’s adaptation of the following research, not an exercise tested in those studies.</p>${a.evidence.map(id=>{const x=C.sources.find(s=>s.id===id);return `<p><a href="${x.url}" target="_blank" rel="noopener noreferrer">${esc(x.citation)}</a>: ${esc(x.use)} ${esc(x.limit)}</p>`}).join('')}</details><div class="path-step-actions">${link('#practice','Choose another activity')}${link('#workbook','Review my workbook')}</div></article>`,'practice')}
 function workbook(){const s=read();return shell(`<section class="path-heading"><h1>Your thinking.<br><em>In one place.</em></h1><p>Your learning notes form a preliminary research blueprint. Keep revising it and check the reasoning with a supervisor.</p><div class="path-actions"><button class="path-button" type="button" data-path-export>Download readable workbook</button>${link('#backup','Back up the editable workbook')}</div><p role="status" data-export-status class="path-muted">Readable downloads are Markdown. A workspace JSON backup preserves editable notes and practice.</p></section><div class="path-workbook">${C.steps.map((step,i)=>`<section><div class="path-section-title"><h2>${esc(step.short)}</h2><a href="#learn/${i}">Edit step ${i+1} ↗</a></div><dl>${step.fields.map(([k,label])=>`<dt>${esc(label)}</dt><dd class="${s.fields[k]?.trim()?'':'path-missing'}">${s.fields[k]?.trim()?esc(s.fields[k]):'Not recorded yet — return to this step when ready.'}</dd>`).join('')}</dl></section>`).join('')}<section><h2>Your practice and revisions</h2>${C.activities.filter(a=>s.practice[a.id]?.attempt).map(a=>`<details><summary>${esc(a.title)}</summary><h3>First attempt</h3>${a.options&&Number.isInteger(s.practice[a.id].choice)?`<p>Chosen interpretation: ${esc(a.options[s.practice[a.id].choice])}</p>`:''}<p>${esc(s.practice[a.id].attempt)}</p><h3>Revision</h3><p>${esc(s.practice[a.id].revision||'No revision recorded yet.')}</p>${link('#practice/'+a.id,'Revisit this activity')}</details>`).join('')||`<p>No practice attempts yet. ${link('#practice','Choose a practice activity')}</p>`}</section></div><section class="path-more"><h2>Ready to work with real sources?</h2><p>Create or open a research project for your source library, evidence, synthesis and proposal. This workbook stays separate so your project text is never overwritten.</p>${link('#research','Open research studio','path-button')}<p>Writing in the full lesson editors stays in your <a href="#notebook/draft">full lesson drafts</a>. It is separate from this guided workbook.</p><p>To request feedback, download your workbook and share it yourself through a channel you trust. REI sends no messages and issues no certificates.</p></section>`,'workbook')}
 function evidence(){return shell(`<section class="path-heading"><h1>A learning design<br>you can <em>inspect.</em></h1><p>The seminar proposal supplies the pathway. Published research informs how you practise. REI’s activities are adaptations; their educational impact has not yet been measured.</p></section><section class="path-evidence"><h2>What comes from the writeshop?</h2><p>The research mindset, ideas and questions, source search/evaluation, literature synthesis, a preliminary framework and blueprint, and reflection follow the supplied activity proposal. The original nine lessons and research tools deepen those stages.</p><h2>What informs the extra practice?</h2>${C.sources.map(x=>`<article><h3>${esc(x.title)}</h3><a href="${x.url}" target="_blank" rel="noopener noreferrer">${esc(x.citation)} ↗</a><p>${esc(x.finding)}</p><dl><dt>REI’s adaptation</dt><dd>${esc(x.use)}</dd><dt>Evidence boundary</dt><dd>${esc(x.limit)}</dd></dl></article>`).join('')}<h2>What still needs evaluation?</h2><p>Expert curriculum review, student usability tests and an appropriate learning evaluation are still needed. A filled workbook or correct scenario answer does not establish research readiness, ethical approval or mastery. Use disciplinary and institutional guidance.</p></section>`)}
 function save(s,message='Saved on this device.'){const ok=window.REILearningStore.writePath(s);C.steps.forEach((step,i)=>{const count=step.fields.filter(([k])=>s.fields[k]?.trim()).length;document.querySelectorAll('.path-outline a[href="#learn/'+i+'"] small').forEach(el=>el.textContent=count?count+' of '+step.fields.length+' prompts have notes'+(ok?'':' in this session'):'No notes yet')});document.querySelectorAll('[data-path-status]').forEach(el=>el.textContent=ok?message:'Not saved to browser storage. Your text is kept in this session. Retry saving or download a backup before leaving.');return ok}
 function capture(form){const s=read(),values=Object.fromEntries(new FormData(form));if(form.dataset.pathForm!==undefined){for(const [key] of C.steps[Number(form.dataset.pathForm)].fields)s.fields[key]=String(values[key]||'');s.last=Number(form.dataset.pathForm)}else{const id=form.dataset.practiceForm,r=s.practice[id]||{choice:null,reviewed:null,revealed:false};r.attempt=String(values.attempt||'');if('revision'in values)r.revision=String(values.revision||'');r.choice='choice'in values?Number(values.choice):null;s.practice[id]=r}return s}
 document.addEventListener('input',event=>{const form=event.target.closest('[data-path-form],[data-practice-form]');if(form)save(capture(form))});
 document.addEventListener('change',event=>{const form=event.target.closest('[data-practice-form]');if(form)save(capture(form))});
 document.addEventListener('submit',event=>{const form=event.target;if(!form.matches('[data-path-form],[data-practice-form]'))return;event.preventDefault();const s=capture(form);if(form.dataset.pathForm!==undefined){save(s);return}const a=C.activities.find(x=>x.id===form.dataset.practiceForm),r=s.practice[a.id];if(!r.attempt.trim()||(a.options&&r.choice===null)){form.querySelector('[data-path-status]').textContent='Write your explanation'+(a.options?' and choose an interpretation':'')+' before comparing.';return}r.revealed=true;save(s);const panel=form.querySelector('#path-comparison');panel.hidden=false;panel.innerHTML=comparison(a,r);panel.tabIndex=-1;panel.focus({preventScroll:true})});
 document.addEventListener('click',event=>{const exportButton=event.target.closest('[data-path-export]');if(exportButton){const url=URL.createObjectURL(new Blob([C.markdown(read())],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='rei-learning-workbook.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);document.querySelector('[data-export-status]').textContent='Workbook download requested. Check that your browser kept the file.'}const reviewed=event.target.closest('[data-path-reviewed]');if(reviewed){const form=reviewed.closest('form'),s=capture(form),r=s.practice[reviewed.dataset.pathReviewed];if(!r.revision?.trim()){form.querySelector('[data-path-status]').textContent='Write a revision and explain what changed before recording this visit.';return}r.reviewed=new Date().toISOString();save(s,'Revision saved and this visit recorded. Return later to try a fresh example.')}});
 function contextBar(){document.querySelector('#path-return')?.remove();const hash=location.hash;if(!/^#(lesson|resource|workshop)\//.test(hash))return;const bar=document.createElement('nav');bar.id='path-return';bar.className='path-return';bar.setAttribute('aria-label','Return to your learning');bar.innerHTML='<a href="#learn">← Learning path</a><a href="#practice">Practice lab</a><a href="#workbook">My workbook</a>';document.querySelector('#main').prepend(bar)}
 addEventListener('rrh:route',contextBar);
 window.REILearningPath={landing,dashboard,stepView,practiceHome,activityView,workbook,evidence};
})();
